<template>
  <div ref="msgListRef" class="msg-list" @scroll="handleScroll" :style="containerStyle">
    <!-- 加载更多提示（顶部） -->
    <div v-if="loadingType === 'more'" class="loading-more">
      <div class="loading-spinner"></div>
      <span>{{ t('loading') }}</span>
    </div>

    <div v-for="(item,index) in msgList" :key="item.id" @mouseenter="handleMouseEnter(index)"
      @mouseleave="handleMouseLeave(index)"
      :class="['message-container', { 'user-message': item.role === MSG_ROLE_USER, 'assistant-message': item.role === MSG_ROLE_ASSISTANT, 'first-message': index === 0 }]">
      <div
        :class="['message-content-wrapper', { 'user-content': item.role === MSG_ROLE_USER, 'assistant-content': item.role === MSG_ROLE_ASSISTANT }]">
        <msg-item-text :ref="el => { if(el) setItemRef(item.id, el) }" :content="item.content" :role="item.role"
          :isMarkdown="item.isMarkdown" :typing="item.typing" :showLoading="item.showLoading"
          :hasThinking="item.hasThinking" :thinkingProcess="item.reasoning_content"
          :thinkingStatus="item.thinking_status" :message-status="item.messageStatus" :isRetrying="item.isRetrying"
          :search_citations="item.search_citations" @onFinish="onFinish(item.id)" @onRetry="onRetryMessage(item.id)">
          <template #footer>
            <div class="footer-container"
              :style="{justifyContent: item.role === MSG_ROLE_USER ? 'flex-end' : 'flex-start'}">
              <!-- PC端消息操作栏 -->
              <msg-action-bar
                v-if="item.messageStatus !== MESSAGE_STATUS.FAILED && !item.showLoading && item.content && ((index === msgList.length - 1 || currentMouseIndex === index))"
                :content="item.content" :messageId="item.id" :role="item.role" :showRegenerate="true" :showShare="true"
                :showLike="true" :showDislike="true" :showMore="true" @onRegenerate="onRegenerateMessage(item.id)"
                @onFeedback="onMessageFeedback" @onReportIssue="onReportIssue" />
            </div>
          </template>
        </msg-item-text>
      </div>
    </div>
    <div ref="lastMsgRef" class="last-msg-ref-small"></div>

    <!-- PC端反馈弹窗 -->
    <feedback ref="feedbackRef" />
  </div>
</template>

<script setup>
import { ref, onMounted, onUnmounted, computed, nextTick, onBeforeUnmount, watch } from 'vue';
import { useI18n } from 'vue-i18n';
import MsgItemText from '@/views/alien/components/msg-item-text.vue';
import MsgActionBar from '@/components/business/msg-action-bar.vue';
import Feedback from '@/components/dialog/feedback.vue';
import { pxToRem } from '@/utils/px-to-rem';
import { ApiChat } from '@/api/api-chat';
import { MSG_ROLE_USER, MSG_ROLE_ASSISTANT, MESSAGE_STATUS, onSendParseMsg, onAIParseMsg } from '@/types/msg.ts';
import { useSmoothScroll } from '@/utils/util';
import { useConversationStore } from '@/store/modules/conversation';

const { smoothScrollToRef } = useSmoothScroll();
const { t } = useI18n();

const props = defineProps({
  sessionId: {
    type: [Number, String],
    default: 0,
  },
  paddingTop: {
    type: String,
    default: pxToRem('10px')
  }
});
const conversationStore = useConversationStore();

const emit = defineEmits(['onLoadComplete', 'onFinishTyping', 'onRetryMessage']);

// 消息列表
const msgList = ref([]);
const msgListRef = ref(null);
const lastMsgRef = ref(null);

// 分页和加载状态
const pageSize = ref(20);
const hasMore = ref(false);
const isLoading = ref(false);
const loadingType = ref('none'); // 'none', 'initial', 'more'
const isFirstLoad = ref(true);
const cursor = ref(null); // 添加cursor字段，用于分页

// 自动滚动控制 - 优化后的状态变量
const autoScroll = ref(true);
const lastScrollTop = ref(0);
const isAutoScrolling = ref(false); // 标记是否正在自动滚动
const scrollDebounceFrame = ref(null); // 滚动防抖帧ID
const contentObserver = ref(null); // 内容变化观察器

// 消息组件引用
const itemRefs = ref({});

// 反馈弹窗引用
const feedbackRef = ref(null);

// 当前鼠标所在的元素
const currentMouseIndex = ref(-1);

// 容器样式
const containerStyle = computed(() => {
  return {
    paddingTop: props.paddingTop
  };
});

// 设置消息组件的引用
const setItemRef = (id, el) => {
  itemRefs.value[id] = el;
};

// 获取特定消息组件的引用
const getItemRef = (id) => {
  return itemRefs.value[id];
};

// 优化后的滚动处理函数
const handleScroll = (e) => {
  const el = e.target;
  const currentScrollTop = el.scrollTop;
  const scrollHeight = el.scrollHeight;
  const clientHeight = el.clientHeight;

  // 判断是否滚动到底部（允许50px的误差，确保能正确检测到底部）
  const isAtBottom = scrollHeight - (currentScrollTop + clientHeight) <= 50;

  // 如果正在自动滚动，只处理底部检测，不处理其他逻辑
  if (isAutoScrolling.value) {
    // 即使在自动滚动期间，也要检测是否到达底部
    if (isAtBottom) {
      autoScroll.value = true;
    }
    return;
  }

  // 计算滚动方向
  const isScrollingUp = currentScrollTop < lastScrollTop.value;
  const isScrollingDown = currentScrollTop > lastScrollTop.value;

  // 用户手动滚动逻辑
  if (isScrollingUp) {
    // 用户向上滚动，禁用自动滚动
    if (autoScroll.value) {
      autoScroll.value = false;
    }
  } else if (isScrollingDown || isAtBottom) {
    // 用户向下滚动或到达底部，检查是否应该启用自动滚动
    if (isAtBottom && !autoScroll.value) {
      autoScroll.value = true;
    }
  }

  // 检查是否向上滚动且接近顶部，加载更多消息
  const SCROLL_THRESHOLD = 50;
  if (
    isScrollingUp &&
    currentScrollTop <= SCROLL_THRESHOLD &&
    !isLoading.value &&
    hasMore.value
  ) {
    loadMoreMessages();
  }

  // 更新上次滚动位置
  if (!isLoading.value) {
    lastScrollTop.value = currentScrollTop;
  }
};

// 优化后的滚动到底部函数
const onScrollMsgBottom = async () => {
  if (!autoScroll.value || !msgListRef.value) return;

  // 标记正在自动滚动
  isAutoScrolling.value = true;

  try {
    const scrollElement = msgListRef.value;

    // 使用多次尝试机制处理动态高度变化
    const scrollToBottomWithObserver = () => {
      return new Promise(resolve => {
        let scrollAttempts = 0;
        const maxAttempts = 3;

        const performScroll = () => {
          const currentHeight = scrollElement.scrollHeight;
          scrollElement.scrollTop = currentHeight;

          scrollAttempts++;

          // 使用requestAnimationFrame检查是否需要再次滚动
          requestAnimationFrame(() => {
            const newHeight = scrollElement.scrollHeight;

            // 如果高度还在变化且未达到最大尝试次数，继续滚动
            if (newHeight > currentHeight && scrollAttempts < maxAttempts) {
              performScroll();
            } else {
              // 最终确保滚动到底部
              scrollElement.scrollTop = scrollElement.scrollHeight;
              isAutoScrolling.value = false;
              resolve();
            }
          });
        };

        performScroll();
      });
    };

    await scrollToBottomWithObserver();
  } catch (error) {
    console.error('Scroll error:', error);
    isAutoScrolling.value = false;
  }
};

// 设置内容变化观察器
const setupContentObserver = () => {
  if (!msgListRef.value) return;

  // 清理之前的观察器
  if (contentObserver.value) {
    contentObserver.value.disconnect();
  }

  // 创建新的观察器
  contentObserver.value = new MutationObserver((mutations) => {
    // 只有在自动滚动启用且不是用户手动滚动时才响应内容变化
    if (!autoScroll.value || isAutoScrolling.value) return;

    let shouldScroll = false;

    mutations.forEach((mutation) => {
      // 检查是否有子节点变化或文本内容变化
      if (mutation.type === 'childList' || mutation.type === 'characterData') {
        shouldScroll = true;
      }
      // 检查是否有属性变化（可能影响布局）
      if (mutation.type === 'attributes' &&
          (mutation.attributeName === 'style' || mutation.attributeName === 'class')) {
        shouldScroll = true;
      }
    });

    if (shouldScroll) {
      // 再次检查是否在底部，只有在底部时才自动滚动
      const scrollElement = msgListRef.value;
      const scrollHeight = scrollElement.scrollHeight;
      const scrollTop = scrollElement.scrollTop;
      const clientHeight = scrollElement.clientHeight;
      const isAtBottom = scrollHeight - (scrollTop + clientHeight) <= 50;

      if (isAtBottom) {
        // 清除之前的防抖帧
        if (scrollDebounceFrame.value) {
          cancelAnimationFrame(scrollDebounceFrame.value);
        }

        // 使用requestAnimationFrame进行防抖
        scrollDebounceFrame.value = requestAnimationFrame(() => {
          nextTick(() => {
            onScrollMsgBottom();
          });
        });
      }
    }
  });

  // 开始观察消息列表容器的变化
  contentObserver.value.observe(msgListRef.value, {
    childList: true,
    subtree: true,
    characterData: true,
    attributes: true,
    attributeFilter: ['style', 'class']
  });
};

const handleMouseEnter = (index) => {
  currentMouseIndex.value = index;
};

const handleMouseLeave = (index) => {
  currentMouseIndex.value = -1;
};

// 加载消息列表
const loadMessages = async (isInitial = false, showLoading = true) => {
  // 如果是初始加载或正在加载中，重置状态
  if (isInitial) {
    cursor.value = null; // 重置cursor
    isFirstLoad.value = true;
    conversationStore.setCurrentConversationId(props.sessionId)
  } else if (isLoading.value || !hasMore.value) {
    // 非初始加载时，如果正在加载或没有更多数据，则直接返回
    return;
  }

  // 设置加载状态
  if (showLoading) {
    isLoading.value = true;
    loadingType.value = isInitial ? 'initial' : 'more';
  }

  // 记录滚动位置（仅在加载更多时需要）
  let oldScrollHeight = 0;
  const scrollElement = msgListRef.value;

  if (!isInitial && scrollElement) {
    oldScrollHeight = scrollElement.scrollHeight;
  }

  try {
    // 确保sessionId存在
    if (!props.sessionId) {
      isLoading.value = false;
      loadingType.value = 'none';
      return;
    }

    // 先从store中获取会话详情（包含消息和分页信息）
    const cachedDetail = conversationStore.getConversationDetail(props.sessionId);

    // 如果有缓存数据且是初始加载，直接使用缓存数据
    if (cachedDetail && cachedDetail.messages && cachedDetail.messages.length > 0 && isInitial) {
      msgList.value = cachedDetail.messages;
      hasMore.value = cachedDetail.hasMore || false; // 使用缓存的hasMore状态
      cursor.value = cachedDetail.cursor || (cachedDetail.messages.length > 0 ? cachedDetail.messages[0].id : null);
      // 使用nextTick确保DOM已更新
      nextTick(() => {
        isFirstLoad.value = false;
        onScrollMsgBottom();
      });

      // 通知父组件加载完成
      emit('onLoadComplete',isInitial);
      isLoading.value = false;
      loadingType.value = 'none';
      return;
    }

    // 如果没有缓存数据或是加载更多，从API获取
    const res = await ApiChat.getChatMessageList(props.sessionId, pageSize.value, cursor.value || null);

    if (res.data && Array.isArray(res.data.items) && res.data.items.length > 0) {
      // 处理消息数据 - 聊天页面需要倒序
      const newMessages = [...res.data.items].reverse().map(item => {
        if (item.role === MSG_ROLE_USER) {
          return onSendParseMsg(item);
        } else {
          return onAIParseMsg(item, false);
        }
      });

      // 如果是初始加载，替换现有消息；否则添加到顶部
      if (isInitial) {
        msgList.value = newMessages;
      } else {
        msgList.value = [...newMessages, ...msgList.value];
      }

      // 使用后端返回的has_more字段判断是否还有更多数据
      hasMore.value = res.data.has_more === true;

      // 更新cursor为最后一个消息的id（因为我们反转了消息列表，所以最后一个消息是最早的）
      if (res.data.items.length > 0 && hasMore.value) {
        cursor.value = res.data.items[res.data.items.length - 1].id;
      } else {
        cursor.value = null; // 如果没有更多数据，重置cursor
      }

      // 使用nextTick确保DOM已更新
      nextTick(() => {
        if (isInitial) {
          // 初始加载时滚动到底部
          isFirstLoad.value = false;
          onScrollMsgBottom();
        } else if (scrollElement) {
          // 加载更多时保持滚动位置，防止页面跳动
          const newScrollHeight = scrollElement.scrollHeight;
          scrollElement.scrollTop = newScrollHeight - oldScrollHeight;
        }
      });

      // 更新store缓存，包含分页信息
      conversationStore.clearConversationCache(props.sessionId);
      conversationStore.cacheConversationDetail(props.sessionId, msgList.value, hasMore.value, cursor.value);

      // 通知父组件加载完成
      emit('onLoadComplete', isInitial);
    } else {
      // 没有数据或数据格式不正确
      hasMore.value = false;
      cursor.value = null; // 重置cursor
      if (isInitial) {
        msgList.value = []; // 清空消息列表

        // 初始化一个空的会话缓存
        conversationStore.cacheConversationDetail(props.sessionId, [], false, null);

        // 通知父组件加载完成
        emit('onLoadComplete',isInitial);
      }
    }
  } catch (error) {
    console.error('Failed to load messages:', error);
  } finally {
    setTimeout(() => {
      isLoading.value = false;
      loadingType.value = 'none';
    }, 300);
  }
};

// 加载更多消息
const loadMoreMessages = () => loadMessages(false);

// 初始加载消息
const getMsgList = (isInitial = true, showLoading = true) => loadMessages(isInitial, showLoading);

// 添加新消息到列表
const addMessage = (message) => {
  // 添加消息到列表
  msgList.value.push(message);
  // 启用自动滚动
  autoScroll.value = true;
  // 滚动到底部
  nextTick(() => {
    onScrollMsgBottom();
  });
};

// 消息打字完成回调
const onFinish = (id) => {
  emit('onFinishTyping', id);
};

// 重试消息
const onRetryMessage = (messageId) => {
  emit('onRetryMessage', messageId);
};

// 重新生成消息
const onRegenerateMessage = (messageId) => {
  console.log('Regenerate message:', messageId);
  emit('onRetryMessage', messageId); // 复用重试逻辑
};

// 消息反馈处理
const onMessageFeedback = (feedbackData) => {
  console.log('Message feedback:', feedbackData);
  // 这里可以调用API发送反馈数据
  // 暂时只打印日志
};

// 举报问题处理
const onReportIssue = (reportData) => {
  console.log('Report issue:', reportData);
  // 显示反馈弹窗
  if (feedbackRef.value) {
    feedbackRef.value.show(reportData.messageId);
  }
};

// 监听sessionId变化，设置内容观察器
watch(() => props.sessionId, () => {
  nextTick(() => {
    setupContentObserver();
  });
}, { immediate: true });

// 组件销毁时清理资源
onBeforeUnmount(() => {
  if (scrollDebounceFrame.value) {
    cancelAnimationFrame(scrollDebounceFrame.value);
    scrollDebounceFrame.value = null;
  }

  if (contentObserver.value) {
    contentObserver.value.disconnect();
    contentObserver.value = null;
  }
});

// 对外暴露方法
defineExpose({
  addMessage,
  getMsgList,
  getItemRef,
  msgList
});
</script>

