<template>
  <div class="feedback-dialog" v-if="dialogVisible">
    <!-- 遮罩层 -->
    <div class="dialog-overlay" @click="handleClose"></div>

    <!-- 弹窗主体 -->
    <div class="dialog-container">
      <!-- 标题区域 -->
      <div class="dialog-header">
        <h2 class="dialog-title">{{ t('reportIssue') }}</h2>
        <div class="header-actions">
          <div class="close-btn" @click="handleClose">×</div>
        </div>
      </div>

      <!-- 内容区域 -->
      <div class="dialog-content">
        <form class="form-container" @submit.prevent="submitForm">
          <!-- 反馈类型 -->
          <div class="form-field">
            <label class="form-label">{{ t('feedbackType') }}</label>
            <div class="select-container" @click="toggleTypeDropdown">
              <div class="select-input">
                <span v-if="feedbackData.type" class="select-value">
                  {{ getSelectedTypeLabel() }}
                </span>
                <span v-else class="select-placeholder">
                  {{ t('selectReportType') }}
                </span>
                <div class="select-arrow" :class="{ 'select-arrow-open': showTypeDropdown }">
                  <svg width="13" height="7" viewBox="0 0 13 7" fill="none">
                    <path d="M1 1L6.5 6L12 1" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>
                  </svg>
                </div>
              </div>
              <!-- 下拉选项 -->
              <div v-if="showTypeDropdown" class="select-dropdown">
                <div
                  v-for="option in feedbackTypeOptions"
                  :key="option.value"
                  class="select-option"
                  @click="selectType(option)"
                >
                  {{ option.label }}
                </div>
              </div>
            </div>
            <div v-if="errors.type" class="form-error">{{ errors.type }}</div>
          </div>

          <!-- 反馈内容 -->
          <div class="form-field">
            <label class="form-label">{{ t('yourFeedback') }}</label>
            <textarea
              v-model="feedbackData.content"
              class="form-textarea"
              :placeholder="t('feedbackPlaceholder')"
              rows="6"
              @blur="validateField('content')"
            ></textarea>
            <div v-if="errors.content" class="form-error">{{ errors.content }}</div>
          </div>
        </form>
      </div>

      <!-- 底部操作栏 -->
      <div class="dialog-footer">
        <button type="button" @click="handleCancel" class="cancel-btn">
          {{ t('cancel') }}
        </button>
        <button
          type="button"
          :disabled="!isFormValid || isLoading"
          :class="['send-btn', { 'send-btn-disabled': !isFormValid || isLoading }]"
          @click="submitForm"
        >
          {{ isLoading ? t('loading') : t('send') }}
        </button>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, computed, watch, onMounted, onUnmounted } from "vue";
import { useI18n } from "vue-i18n";

const props = defineProps({
  visible: {
    type: Boolean,
    default: false,
  },
});

const emit = defineEmits(["update:visible", "cancel", "submit"]);

const { t } = useI18n();

const isLoading = ref(false);

// 对话框显示控制
const dialogVisible = ref(false);

// 是否显示类型下拉菜单
const showTypeDropdown = ref(false);

// 反馈类型选项
const feedbackTypeOptions = computed(() => [
  { value: "inaccurate", label: t('inaccurateInformation') },
  { value: "bug", label: t('reportBug') },
  { value: "harmful", label: t('harmfulContent') },
  { value: "childSafety", label: t('childSafetyConcern') },
]);

// 反馈数据
const feedbackData = ref({
  type: "",
  content: "",
  messageId: null
});

// 表单错误
const errors = ref({
  type: "",
  content: ""
});

// 判断表单是否有效
const isFormValid = computed(() => {
  return feedbackData.value.type && feedbackData.value.content && !errors.value.type && !errors.value.content;
});

// 生命周期钩子
onMounted(() => {
  if (props.visible) {
    dialogVisible.value = true;
  }
  // 添加全局点击事件监听
  document.addEventListener('click', handleOutsideClick);
});

onUnmounted(() => {
  // 移除全局点击事件监听
  document.removeEventListener('click', handleOutsideClick);
});

// 监听props.visible变化
watch(
  () => props.visible,
  (newVal) => {
    dialogVisible.value = newVal;
  }
);

// 监听dialogVisible变化
watch(
  () => dialogVisible.value,
  (newVal) => {
    emit("update:visible", newVal);
  }
);

// 处理下拉菜单外部点击
const handleOutsideClick = (event) => {
  const selectContainer = event.target.closest('.select-container');
  if (!selectContainer && showTypeDropdown.value) {
    showTypeDropdown.value = false;
  }
};

// 切换类型下拉菜单
const toggleTypeDropdown = () => {
  showTypeDropdown.value = !showTypeDropdown.value;
};

// 选择反馈类型
const selectType = (option) => {
  feedbackData.value.type = option.value;
  showTypeDropdown.value = false;
  validateField('type');
};

// 获取选中类型的标签
const getSelectedTypeLabel = () => {
  const selected = feedbackTypeOptions.value.find(option => option.value === feedbackData.value.type);
  return selected ? selected.label : '';
};

// 验证字段
const validateField = (field) => {
  errors.value[field] = '';

  if (field === 'type' && !feedbackData.value.type) {
    errors.value.type = `${t('feedbackType')} ${t('isRequired')}`;
  }

  if (field === 'content' && !feedbackData.value.content.trim()) {
    errors.value.content = `${t('yourFeedback')} ${t('isRequired')}`;
  }
};

// 验证整个表单
const validateForm = () => {
  validateField('type');
  validateField('content');
  return isFormValid.value;
};

// 关闭弹窗
const handleClose = () => {
  dialogVisible.value = false;
  resetForm();
};

// 取消按钮
const handleCancel = () => {
  dialogVisible.value = false;
  emit("cancel");
  resetForm();
};

// 重置表单
const resetForm = () => {
  feedbackData.value = {
    type: "",
    content: "",
    messageId: null
  };
  errors.value = {
    type: "",
    content: ""
  };
  showTypeDropdown.value = false;
};

// 提交表单
const submitForm = () => {
  if (!validateForm() || isLoading.value) return;

  isLoading.value = true;

  // 模拟异步提交
  setTimeout(() => {
    // 创建反馈数据
    const feedback = {
      ...feedbackData.value,
    };

    isLoading.value = false;
    // 发送提交事件
    emit("submit", feedback);

    // 关闭弹窗
    dialogVisible.value = false;

    // 显示成功消息
    console.log('Feedback submitted successfully');

    // 重置表单
    resetForm();
  }, 1000);
};

// 显示弹窗的方法
const show = (messageId = null) => {
  dialogVisible.value = true;
  // 可以保存messageId用于后续的提交
  if (messageId) {
    feedbackData.value.messageId = messageId;
  }
};

// 暴露方法给父组件
defineExpose({
  show
});
</script>

